def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                _, wtime = cache[key]
                if t < wtime + ttl:
                    # still valid, update in place
                    cache[key] = (value, t)
                    cache.move_to_end(key)
                    continue
                else:
                    # expired, remove first
                    del cache[key]

            # key absent now, need to insert
            if len(cache) >= capacity:
                cache.popitem(last=False)

            cache[key] = (value, t)
            cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                value, wtime = cache[key]
                if t < wtime + ttl:
                    results.append(value)
                    cache.move_to_end(key)
                else:
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

